package com.ollie.tierborne.network;
import com.ollie.tierborne.*;import com.ollie.tierborne.data.*;import net.minecraft.network.FriendlyByteBuf;import net.minecraft.server.level.ServerPlayer;import net.minecraftforge.network.NetworkEvent;import java.util.function.Supplier;
public record SetMovementSpeedLimitPacket(int percent){public static void encode(SetMovementSpeedLimitPacket p,FriendlyByteBuf b){b.writeVarInt(p.percent);}public static SetMovementSpeedLimitPacket decode(FriendlyByteBuf b){return new SetMovementSpeedLimitPacket(b.readVarInt());}public static void handle(SetMovementSpeedLimitPacket p,Supplier<NetworkEvent.Context>s){NetworkEvent.Context c=s.get();c.enqueueWork(()->{ServerPlayer player=c.getSender();if(player==null)return;PlayerProgressSavedData data=PlayerProgressSavedData.get(player.getServer());PlayerProgress progress=data.get(player.getUUID());if(progress.setMovementSpeedLimitPercent(p.percent)){data.changed();TierborneEvents.applySkillEffects(player,progress);ModNetwork.sync(player);}});c.setPacketHandled(true);}}
